ALTER TABLE problem_lineage ADD COLUMN identity TEXT;
        UPDATE problem_lineage l SET identity = p.identity
            FROM problem p
            WHERE p.workspace_id = l.workspace_id AND p.id = COALESCE(l.problem_id, l.prior_problem_id);
        ALTER TABLE problem_lineage ALTER COLUMN identity SET NOT NULL;
        CREATE INDEX idx_problem_lineage_identity ON problem_lineage (workspace_id, identity);
